import hashlib

from datetime import datetime
from random import randint


def generate_md5():
    """Method returns checksum generated using MD5"""
    string = str(datetime.now()) + str(randint(0, 1000000))
    checksum = hashlib.md5(string.encode('utf-8'))
    return checksum.hexdigest()


def generate_sha1():
    """Method returns checksum generated using SHA1"""
    string = str(datetime.now()) + str(randint(0, 1000000))
    checksum = hashlib.sha1(string.encode('utf-8'))
    return checksum.hexdigest()
